/// <summary>
/// This is an event handler class for CustInvoiceLine table
/// </summary>
class METCustInvoiceLine_EventHandler
{

}

Method.Source:
/// <summary>
///  Updates the TaxItemGroup status for custInvoiceLine
/// </summary>
/// <param name="args"></param>
[PostHandlerFor(tableStr(CustInvoiceLine), tableMethodStr(CustInvoiceLine, initFromCustInvoiceTable))]
public static void CustInvoiceLine_Post_initFromCustInvoiceTable(XppPrePostArgs args)
{
    CustInvoiceLine     custInvoiceLine = args.getThis() as CustInvoiceLine;
    CustInvoiceTable    custInvoiceTable;
    TAMRebateTrans      rebateTrans;

    select firstonly METTaxItemGroup, METItemTypeDescription from  rebateTrans
               exists join custInvoiceTable 
            where custInvoiceTable.TAMRebateTransId == rebateTrans.RebateTransId 
        && custInvoiceTable.RecId == custInvoiceLine.ParentRecId;

    custInvoiceLine.TaxItemGroup    = rebateTrans.METTaxItemGroup;
    custInvoiceLine.Description     = rebateTrans.METItemTypeDescription;
}
